"use client";

import { useState } from "react";
import { addProductGuideSizes, validateProductSizeGuide, type ProductSizeGuide } from "@/mobile/src/lib/product-size-guide";

type Props = { value: ProductSizeGuide | null; onChange: (guide: ProductSizeGuide | null) => void; sizes: string[]; clothing: boolean };
export default function ProductSizeGuideEditor({ value, onChange, sizes, clothing }: Props) {
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");
  const [preview, setPreview] = useState(false);
  const blank = (): ProductSizeGuide => ({ title: "Guide des tailles", columns: clothing ? ["Taille", "FR", "Poitrine (cm)", "Tour de taille (cm)"] : ["EU", "US", "UK", "CM"], rows: (sizes.length ? sizes : [""]).slice(0, 50).map(size => [size, "", "", ""]), note: "" });
  async function copyDefault() {
    setLoading(true); setError("");
    try {
      const response = await fetch("/api/size-guide", { cache: "no-store" });
      if (!response.ok) throw new Error();
      const data = await response.json();
      const source = clothing ? data.clothing : data.shoes;
      if (!Array.isArray(source) || !source.length) throw new Error();
      const copied = validateProductSizeGuide({ ...blank(), rows: source.slice(0, 50).map(row => clothing ? [row.label, row.fr, row.poitrine, row.taille] : [row.eu, row.us, row.uk, row.cm]) });
      if (!copied) throw new Error();
      onChange(addProductGuideSizes(copied, sizes));
    } catch { setError("Impossible de copier le guide. Réessayez ou remplissez votre tableau."); }
    finally { setLoading(false); }
  }
  const input = "min-h-11 w-full rounded-xl border border-neutral-200 bg-white px-3 py-2 text-sm focus:border-emerald-600 focus:outline-none focus:ring-2 focus:ring-emerald-100";
  const button = "min-h-11 rounded-xl border border-neutral-200 bg-white px-3 text-xs font-semibold transition hover:border-emerald-500 hover:bg-emerald-50 disabled:opacity-40";
  return <section className="mt-5 space-y-4 rounded-2xl border border-neutral-200 bg-white p-4 sm:p-5">
    <div className="border-b border-neutral-100 pb-4"><div className="flex flex-wrap items-center justify-between gap-2"><h3 className="font-bold">Guide des tailles de ce produit</h3><span className="rounded-full bg-emerald-50 px-2.5 py-1 text-[10px] font-bold text-emerald-800">Site + application</span></div><p className="mt-2 text-xs leading-5 text-neutral-500">Personnalisez les tailles et les mesures affichées aux clients. Enregistrez le produit pour mettre à jour son guide sur le site et dans l’application.</p></div>
    <label className="block text-sm font-medium">Tableau à afficher<select disabled={loading} className={`${input} mt-1`} value={value ? "custom" : "store"} onChange={e => onChange(e.target.value === "custom" ? blank() : null)}><option value="store">Guide général de la boutique</option><option value="custom">Tableau personnalisé pour ce produit</option></select></label>
    {!value && <p className="text-xs leading-5 text-neutral-500">Ce produit suit le guide général. Choisissez un tableau personnalisé pour gérer ses propres pointures, demi-pointures et mesures.</p>}
    {value && <fieldset disabled={loading} className="min-w-0 space-y-4 disabled:opacity-60">
      <label className="block text-sm">Titre<input className={`${input} mt-1`} maxLength={80} required value={value.title} onChange={e => onChange({ ...value, title: e.target.value })}/></label>
      <div className="flex flex-wrap gap-2"><button type="button" className={button} onClick={() => void copyDefault()}>{loading ? "Chargement…" : "Copier le guide général"}</button><button type="button" className={button} onClick={() => onChange(addProductGuideSizes(value, sizes))}>Ajouter les tailles du produit</button><button type="button" className={button} onClick={() => onChange({ ...value, rows: [...value.rows].sort((a, b) => a[0].replace(",", ".").localeCompare(b[0].replace(",", "."), "fr", { numeric: true })) })}>Trier les tailles</button></div>
      <p className="text-xs leading-5 text-neutral-500">Saisissez par exemple 41, 41.5 ou 44.5, puis les correspondances US, UK et CM. Les cellules vides affichent « — », sans estimation. Les tailles en vente et leur stock restent gérés séparément.</p>
      <p className="text-xs text-neutral-500">« Copier le guide général » remplace le tableau. « Ajouter les tailles du produit » conserve vos mesures.</p>
      <div className="overflow-x-auto"><table className="w-full min-w-[580px] border-separate border-spacing-2"><thead><tr>{value.columns.map((column, index) => <th key={index}><input aria-label={`Titre colonne ${index + 1}`} required maxLength={30} className={input} value={column} onChange={e => onChange({ ...value, columns: value.columns.map((c, i) => i === index ? e.target.value : c) as ProductSizeGuide["columns"] })}/></th>)}<th><span className="sr-only">Actions</span></th></tr></thead><tbody>{value.rows.map((row, rowIndex) => <tr key={rowIndex}>{row.map((cell, col) => <td key={col}><input aria-label={`Ligne ${rowIndex + 1}, ${value.columns[col]}`} required={col === 0} maxLength={60} className={input} value={cell} onChange={e => onChange({ ...value, rows: value.rows.map((r, i) => i === rowIndex ? r.map((c, j) => j === col ? e.target.value : c) as ProductSizeGuide["rows"][number] : r) })}/></td>)}<td><button type="button" aria-label={`Supprimer la ligne ${rowIndex + 1}`} className="min-h-11 px-3 text-sm text-red-600" onClick={() => onChange({ ...value, rows: value.rows.filter((_, i) => i !== rowIndex) })}>Supprimer</button></td></tr>)}</tbody></table></div>
      <div className="flex flex-wrap items-center gap-2"><button type="button" disabled={value.rows.length >= 50} className={button} onClick={() => onChange({ ...value, rows: [...value.rows, ["", "", "", ""]] })}>+ Ajouter une taille</button><span className="text-xs text-neutral-500">{value.rows.length} / 50 lignes</span><button type="button" className={button} aria-expanded={preview} onClick={() => setPreview(!preview)}>{preview ? "Masquer l’aperçu" : "Aperçu client"}</button></div>
      <label className="block text-sm">Note sous le tableau<input maxLength={500} className={`${input} mt-1`} value={value.note} onChange={e => onChange({ ...value, note: e.target.value })}/></label>
      {!validateProductSizeGuide(value) && <p role="status" className="rounded-xl bg-amber-50 p-3 text-xs leading-5 text-amber-900">Complétez le titre, les quatre en-têtes et la taille de chaque ligne. Chaque taille doit être unique.</p>}
      {preview && <div className="overflow-x-auto rounded-xl border border-neutral-200"><table className="w-full min-w-[360px] table-fixed text-center text-sm"><caption className="bg-neutral-50 p-3 font-semibold">{value.title}</caption><thead className="bg-[#294e3a] text-white"><tr>{value.columns.map((column, i) => <th key={i} className="break-words px-2 py-3">{column}</th>)}</tr></thead><tbody>{value.rows.map((row, i) => <tr key={i} className="border-t border-neutral-100 even:bg-neutral-50">{row.map((cell, j) => <td key={j} className={`break-words px-2 py-3 ${j === 0 ? "font-semibold" : ""}`}>{cell || "—"}</td>)}</tr>)}</tbody></table>{value.note && <p className="border-t p-3 text-xs text-neutral-500">{value.note}</p>}</div>}
    </fieldset>}
    {error && <p role="alert" className="text-sm text-red-600">{error}</p>}
  </section>;
}
